/**
 * generated by stackra gen from the `offline` field of the consumed manifests' actions (`@Action({
 * offline })`) — do not edit
 * Purpose: the offline map: for each consumed action that declared `offline`, what the mutation
 *          queue of @stackra/query may do while the client is offline. Every other action is
 *          online-only and refuses with `offline` at once.
 * Boundary: a queued call keeps its Idempotency-Key and precondition; `onConflict` lists the
 *           resolutions the pending-changes view may offer for a 409. A destructive action at L3 or
 *           above can never queue.
 * Runtime: browser
 */
import {
  ConflictResolution,
  IdMinting,
  OfflineMode,
  OfflinePrecondition,
} from "@stackra/actions";
import { offlineMap } from "@stackra/query";
import { Commerce } from "#stackra/clients";

/** Action → offline policy, exactly as each producer's manifest declares it. */
export const Offline = offlineMap([
  {
    action: Commerce.actions.CreateOrder,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Client,
    precondition: OfflinePrecondition.None,
    retention: "72h",
    onConflict: [ConflictResolution.ServerWins, ConflictResolution.Manual],
  },
  {
    action: Commerce.actions.ArchiveProduct,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Server,
    precondition: OfflinePrecondition.Version,
    retention: "24h",
    onConflict: [
      ConflictResolution.ServerWins,
      ConflictResolution.ClientRetry,
      ConflictResolution.Manual,
    ],
  },
]);
